    let arr = (posts || []).filter(p => forumVisible(p) && (tab === "收藏" || forumBoardsAll().includes(p.board)) && (p.fmt === "xhs") === cardLayout);
    if (tab === "收藏") arr = arr.filter(p => bookmarked.has(p.id));
