  const playAllCloud = (list, srcId) => { if (!list || !list.length) return; onPlayResultList(list); if (gdMusic) return; try { nj("/scrobble?id=" + list[0].id + "&sourceid=" + (srcId || 0) + "&time=240").catch(() => {}); } catch (e) {} };
