  const [list, setList] = useState(profiles.length ? profiles : [{
    id: "p_" + Date.now(),
    name: "",
    baseUrl: "",
    apiKey: "",
    model: "",
    temperature: 0.75
  }]);
  const [curId, setCurId] = useState(activeId || profiles[0] && profiles[0].id || (profiles.length ? profiles[0].id : null));
  const [dd, setDd] = useState(false);
