    if (sec.closet) {
      const g = closetGroups(data[sec.key]);
      const n = g.reduce((a, x) => a + x.sets.length, 0);
      return n ? (g.length > 1 ? g.length + " 场合 · " + n + " 套" : n + " 套") : "";
    }
